/**
 * Cross-language parity: app/js/field_spot.js must agree with the Python it was
 * ported from (ml/src/label_spot.py + the proximity read in
 * ml/src/field_proximity.py) on every golden vector.
 *
 * Two implementations of the same rules drift apart the moment one is edited,
 * and the one a blind user reads is the JS. The vectors are generated BY the
 * Python — ml/tests/test_field_spot_vectors.py, which also fails if the
 * checked-in table (or the @generated vocabulary block in the JS) is stale — so
 * there is exactly one reference here and this file only compares. Nothing is
 * re-implemented on the JS side to make a case pass.
 *
 * What "agree" means per vector type:
 *   spot     the same spots, in the same order: label, start, end and score.
 *            Score is compared EXACTLY: the JS computes 1 - d/L with the same
 *            IEEE ops and rounds to 4 places the way CPython round() does.
 *   lines    the same spots with line_index, same order.
 *   value    the same text after a label span, byte for byte.
 *   extract  the same {field: {value, ok, kind, reason, provenance}} map.
 *
 * Run:  node app/tools/field_spot_contract.js      (exit 0 = parity, 1 = not)
 */

"use strict";

const fs = require("fs");
const path = require("path");
const FS = require("../js/field_spot.js");

const FILE = path.resolve(__dirname, "field_spot_vectors.json");

// ── comparison ────────────────────────────────────────────────────────────────
//
// JSON objects have no order; JSON arrays do. `same` reflects that and nothing
// else, so a mismatch is always a real difference and never key order.

function same(a, b) {
  if (a === b) return true;
  if (a === null || b === null || a === undefined || b === undefined) return false;
  if (Array.isArray(a) || Array.isArray(b)) {
    if (!Array.isArray(a) || !Array.isArray(b) || a.length !== b.length) return false;
    return a.every((x, i) => same(x, b[i]));
  }
  if (typeof a === "object" && typeof b === "object") {
    const ka = Object.keys(a).sort(), kb = Object.keys(b).sort();
    if (!same(ka, kb)) return false;
    return ka.every(k => same(a[k], b[k]));
  }
  return false;
}

const show = v => JSON.stringify(v);
const brief = v => {
  const s = show(v);
  return s.length > 300 ? s.slice(0, 300) + "..." : s;
};

// ── one vector ────────────────────────────────────────────────────────────────

function run(v) {
  switch (v.t) {
    case "spot":
      return { got: FS.spotLabels(v.text, v.threshold), want: v.spots };
    case "lines":
      return { got: FS.spotInLines(v.lines), want: v.spots };
    case "value":
      return { got: FS.valueAfter(v.text, v.span), want: v.value };
    case "extract":
      return { got: FS.extractFields(v.lines, v.spots), want: v.out };
    default:
      return { got: null, want: null, error: `unknown vector type ${v.t}` };
  }
}

function label(v) {
  if (v.t === "spot") return `spot th=${v.threshold} ${show(v.text)}`;
  if (v.t === "lines") return `lines ${show(v.lines.map(l => l.text))}`;
  if (v.t === "value") return `value ${show(v.text)} span=${show(v.span)}`;
  return `extract ${v.name || ""} ${brief((v.lines || []).map(l => l.text))}`;
}

// ── run ───────────────────────────────────────────────────────────────────────

const payload = JSON.parse(fs.readFileSync(FILE, "utf8"));
const vectors = payload.vectors;

let pass = 0, fail = 0;
const byType = {};
const mismatches = [];
for (const v of vectors) {
  byType[v.t] = byType[v.t] || { pass: 0, fail: 0 };
  let r;
  try {
    r = run(v);
  } catch (e) {
    r = { got: `<threw ${e && e.message}>`, want: v.out };
  }
  if (r.error) {
    r.got = r.error;
    r.want = "a known vector type";
  }
  if (same(r.got, r.want)) {
    pass++;
    byType[v.t].pass++;
  } else {
    fail++;
    byType[v.t].fail++;
    mismatches.push(label(v));
    console.log(`FAIL  ${label(v)}`);
    console.log(`      python: ${brief(r.want)}`);
    console.log(`      js:     ${brief(r.got)}`);
  }
}

console.log("\nper-vector-type (python vs javascript):");
for (const t of Object.keys(byType).sort()) {
  const c = byType[t];
  console.log(`  ${t.padEnd(10)} ${String(c.pass).padStart(4)} passed` +
              `${c.fail ? "  " + c.fail + " FAILED" : ""}`);
}

console.log(`\nfield spot contract: ${vectors.length} vectors, ` +
            `${pass} passed, ${fail} FAILED`);
process.exit(fail ? 1 : 0);
